// Logic template
var calc_output = [];

var a = parseFloat(a);
var b = parseFloat(b);
var c = parseFloat(c);
var d = parseFloat(d);
var e = parseFloat(e);
var f = parseFloat(f);

var score = a + b + c + d + e + f;
var point;
if (score == 1) {
    point = ' point';
} else {
    point = ' points';
}

var grade;
if (a + b + c + d + e + f === 6) {
    grade = 'Grade A';
} else if (a + b + c + d + e + f === 5) {
    grade = 'Grade B';
} else if (a === 0 && b + c + d + e + f === 4) {
    grade = 'Grade C';
} else if (a + b === 0 && c + d + e + f === 3) {
    grade = 'Grade D';
} else if (a + b + c === 0 && d + e + f === 2) {
    grade = 'Grade E';
} else if (a + b + c + d === 0 && e + f === 1) {
    grade = 'Grade F';
} else if (a + b + c + d + e + f === 0) {
    grade = 'Grade G';
} else if (a + b + c + d + e + f <= 4) {
    grade = 'Other Grade';
} else {
    grade = 'Grade Undefined';
}

// Output
calc_output.push({
    name: 'mini',
    value: grade,
    value_text: '(' + score + point + ')',
    message: 'Katz Index of Independence in ADL'
});
